package com.domesticservice.finance.service;
import com.domesticservice.finance.repository.support.NativeQueryExecutor;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.autoconfigure.EnableAutoConfiguration;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.context.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="DISCIPLINE_POSTGRES_VERIFY",matches="true")
@SpringBootTest(classes=StaffDisciplinePostgresTests.Config.class,webEnvironment=SpringBootTest.WebEnvironment.NONE,properties={"spring.datasource.url=jdbc:postgresql://localhost:5549/discipline_finance","spring.datasource.username=postgres","spring.datasource.password=discipline_test_only","spring.jpa.hibernate.ddl-auto=none","spring.flyway.enabled=true","clients.identity.base-url=http://127.0.0.1:1"})
class StaffDisciplinePostgresTests {
 @Configuration(proxyBeanMethods=false) @EnableAutoConfiguration @Import({NativeQueryExecutor.class,StaffDisciplineService.class}) static class Config {}
 @Autowired StaffDisciplineService service;@Autowired JdbcTemplate db;@Autowired PlatformTransactionManager manager;long staff;static long next=System.currentTimeMillis();
 @BeforeEach void init(){staff=++next;db.update("INSERT INTO staff_balances(staff_id,available_balance) VALUES (?,20000)",staff);db.update("UPDATE staff_discipline_policy SET penalty_amount=5000,completion_bonus=1000,effective_from=now()-interval '1 day'");}
 Map<String,Object> violation(long assignment){return service.noShow(Map.of("staffId",staff,"bookingId",6000L+assignment,"assignmentId",assignment,"evidence","Verified test deadline and execution status"));}
 long balance(){return db.queryForObject("SELECT available_balance FROM staff_balances WHERE staff_id=?",Long.class,staff);}
 Map<String,Object> action(String kind,long amount,String key){return new TransactionTemplate(manager).execute(s->service.create(staff,null,kind,"QUALITY",amount,"Isolated verification","ADMIN",key,1L,""));}
 @Test void firstTwoWarnThirdDebitsExactlyOnceAndRetainsEvidence(){long a=staff*10;assertEquals("WARNING",violation(a).get("status"));assertEquals("WARNING",violation(a+1).get("status"));assertEquals(20000,balance());assertEquals("APPLIED",violation(a+2).get("status"));assertEquals(15000,balance());violation(a+2);db.update("UPDATE staff_discipline_policy SET penalty_amount=9000");violation(a+2);assertEquals(15000,balance());assertEquals(1,db.queryForObject("SELECT count(*) FROM wallet_transactions w JOIN staff_balances b ON b.id=w.balance_id WHERE b.staff_id=?",Integer.class,staff));assertEquals(3,db.queryForObject("SELECT max(violation_number) FROM staff_discipline_actions WHERE staff_id=?",Integer.class,staff));}
 @Test void insufficientFundsStayPendingAndRetryAfterFunding(){db.update("UPDATE staff_balances SET available_balance=0 WHERE staff_id=?",staff);var a=action("PENALTY",5000,"pending-"+staff);assertEquals("PENDING_FUNDS",a.get("status"));assertNull(a.get("ledger_id"));service.retry();assertEquals(0,balance());db.update("UPDATE staff_balances SET available_balance=6000 WHERE staff_id=?",staff);service.retry();service.retry();assertEquals(1000,balance());assertEquals("APPLIED",db.queryForObject("SELECT status FROM staff_discipline_actions WHERE id=?",String.class,a.get("id")));}
 @Test void manualRewardAndWarningHaveDistinctWalletEffects(){action("REWARD",1000,"reward-"+staff);action("REWARD",1000,"reward-"+staff);action("WARNING",0,"warning-"+staff);assertEquals(21000,balance());assertThrows(org.springframework.web.server.ResponseStatusException.class,()->action("REWARD",2000,"reward-"+staff));}
 @Test void concurrentViolationsSerializeCounterAndLedger()throws Exception{var pool=Executors.newFixedThreadPool(4);try{var futures=new ArrayList<Future<?>>();for(int i=0;i<4;i++){long id=staff*10+i;futures.add(pool.submit(()->violation(id)));}for(var f:futures)f.get(15,TimeUnit.SECONDS);}finally{pool.shutdownNow();}assertEquals(10000,balance());assertEquals(4,db.queryForObject("SELECT max(violation_number) FROM staff_discipline_actions WHERE staff_id=?",Integer.class,staff));}
 @Test void completionBonusRequiresSettlementAndIsIdempotent(){long booking=staff*10;var b=Map.<String,Object>of("id",booking,"status","COMPLETED","startsAt",java.time.Instant.now().toString(),"assignments",List.of(Map.of("id",booking,"staffId",staff,"status","COMPLETED")));new TransactionTemplate(manager).executeWithoutResult(s->service.completed(b));assertEquals(20000,balance());db.update("INSERT INTO staff_incomes(staff_id,booking_id,balance_id,working_hours,service_amount,platform_fee,staff_amount,status,income_date,settled_at) SELECT ?,?,id,1,10000,2000,8000,'SETTLED',CURRENT_DATE,now() FROM staff_balances WHERE staff_id=?",staff,booking,staff);new TransactionTemplate(manager).executeWithoutResult(s->{service.completed(b);service.completed(b);});assertEquals(21000,balance());}
 @Test void auditAndWalletCannotBeDeleted(){var a=action("REWARD",1000,"audit-"+staff);assertThrows(Exception.class,()->db.update("DELETE FROM staff_discipline_actions WHERE id=?",a.get("id")));assertThrows(Exception.class,()->db.update("DELETE FROM wallet_transactions WHERE id=?",a.get("ledger_id")));}
 @Test void forgottenCustomerRefundUsesVerifiedPaymentAndCannotDoubleCredit(){long booking=staff*10,customer=staff+100000;db.update("INSERT INTO payments(booking_id,customer_id,payment_code,amount,payment_method,status,paid_at) VALUES (?,?,?,10000,'WALLET','PAID',now())",booking,customer,"refund-test-"+staff);var body=Map.<String,Object>of("bookingId",booking,"customerId",customer);assertEquals(10000L,service.refundForgotten(body).get("refundedAmount"));service.refundForgotten(body);assertEquals(10000,db.queryForObject("SELECT available_balance FROM customer_wallets WHERE customer_id=?",Long.class,customer));assertEquals(1,db.queryForObject("SELECT count(*) FROM customer_wallet_transactions WHERE customer_id=?",Integer.class,customer));}
 @Test void noRefundForUnpaidCashBooking(){assertEquals(0L,service.refundForgotten(Map.of("bookingId",staff*10,"customerId",staff+100000)).get("refundedAmount"));}
}
